const events=load("game6events"), moves=[];
const getText=r=>r.content.filter(c=>c.type==="text").map(c=>c.text).join("\n");
const first=getText(events[0].response).match(/It plays first: ([A-HJ][1-9]|pass)\./); moves.push({number:1,color:"B",move:first[1]});
for(const e of events.slice(1)){moves.push({number:moves.length+1,color:"W",move:e.move}); const t=getText(e.response);const m=t.match(/Your opponent played ([A-HJ][1-9])\./);if(m)moves.push({number:moves.length+1,color:"B",move:m[1]});else if(t.includes("Your opponent passed."))moves.push({number:moves.length+1,color:"B",move:"pass"});}
store("game6moves",moves);
const f=load("game6final");const b=f.board, cols="ABCDEFGHJ";const ns=p=>{const x=cols.indexOf(p[0]),y=+p[1];return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([a,z])=>a>=0&&a<9&&z>=1&&z<=9).map(([a,z])=>cols[a]+z);};
const counts={B:0,W:0,neutral:0},seen=new Set(),regions=[];
for(const [p,v] of Object.entries(b)){if(v==="X")counts.B++;if(v==="O")counts.W++;if(v!=="."||seen.has(p))continue;const q=[p],points=[],borders=new Set();seen.add(p);while(q.length){const k=q.pop();points.push(k);for(const n of ns(k)){if(b[n]==="."&&!seen.has(n)){seen.add(n);q.push(n);}else if(b[n]!=="."&&b[n])borders.add(b[n]);}}
const owner=borders.size===1?[...borders][0]:null;counts[owner==="X"?"B":owner==="O"?"W":"neutral"]+=points.length;regions.push({points:points.sort(),borders:[...borders],owner});}
store("game6area",{counts,regions,groups:f.groups});text({moves,moveCount:moves.length,passes:moves.filter(x=>x.move==="pass"),area:counts,groups:f.groups});
const sgfCoord=p=>p==="pass"?"":String.fromCharCode(97+cols.indexOf(p[0]))+String.fromCharCode(97+9-+p[1]);
const sgf="(;GM[1]FF[4]CA[UTF-8]SZ[9]RU[Chinese]KM[7]DT[2026-10-05]PB[KataGo human-style 20k]PW[Codex]RE[B+24]GN[Game 6]"+moves.map(m=>`;${m.color}[${sgfCoord(m.move)}]`).join("")+")\n";
const log={game:6,date:"2026-10-05",rank:"20k",player:"W",rules:"Chinese area scoring, simple ko, suicide forbidden",komi:7,result:"B+24",moves,events,finalInspection:load("game6area")};
