const paths=["game-006-log.json","game-006.sgf","game-006.md","AGENTS.md"];
const rs=await Promise.allSettled(paths.map(path=>tools.mcp__desk__read_file({path})));
const files={};
for(let i=0;i<rs.length;i++){if(rs[i].status!=="fulfilled"||rs[i].value.isError)throw new Error("Read failed: "+paths[i]);files[paths[i]]=rs[i].value.content.filter(c=>c.type==="text").map(c=>c.text).join("\n");}
const log=JSON.parse(files["game-006-log.json"]),sgf=files["game-006.sgf"];
const sm=[...sgf.matchAll(/;([BW])\[([a-i]{2})?\]/g)];
if(log.moves.length!==82||sm.length!==82||log.events.length!==42)throw new Error("Record count mismatch");
for(let i=0;i<82;i++){const m=log.moves[i],cols="ABCDEFGHJ",coord=m.move==="pass"?"":String.fromCharCode(97+cols.indexOf(m.move[0]))+String.fromCharCode(97+9-+m.move[1]);if(sm[i][1]!==m.color||(sm[i][2]||"")!==coord)throw new Error("SGF mismatch at "+(i+1));}
if(log.finalInspection.counts.B!==56||log.finalInspection.counts.W!==25||log.finalInspection.counts.neutral!==0)throw new Error("Area mismatch");
text({verified:true,moves:82,events:42,passes:log.moves.filter(m=>m.move==="pass").length,result:log.result,area:log.finalInspection.counts,reviewSaved:files["game-006.md"].includes("NOT seki"),persistentLessonSaved:files["AGENTS.md"].includes("earlier claim of seki was wrong")});
